import SockJS from 'sockjs-client';
import { Client } from '@stomp/stompjs';

class WebSocketService {
  constructor() {
    this.stompClient = null;
    this.connected = false;
    this.subscriptions = [];
  }

  async connect({ token }) {
    if (this.connected) return;

    const socket = new SockJS(`http://localhost:5000/ws`);

    this.stompClient = new Client({
      webSocketFactory: () => socket,
      connectHeaders: {
        Authorization: `Bearer ${token}`
      },
      debug: (str) => {
        // console.log(str);
      },
      reconnectDelay: 3000,
    });

    this.stompClient.onConnect = (frame) => {
      // console.log('Connected: ' + frame);
      this.connected = true;
      // Add any subscriptions or initial messages here
    };

    this.stompClient.onStompError = (frame) => {
      this.connect();
      // console.error('Broker reported error: ' + frame.headers['message']);
      // console.error('Additional details: ' + frame.body);
    };

    this.stompClient.activate();
    return this.stompClient;
  }

  disconnect() {
    if (this.stompClient && this.connected) {
      this.stompClient.deactivate();
      // console.log("Disconnected");
      this.connected = false;
    }
  }

  sendMessage(destination, body) {
    if (this.stompClient && this.connected) {
      this.stompClient.publish({ destination, body });
      // console.log("sent message",destination);
    }
  }


  subscribe(topic, callback) {
    if (this.stompClient && this.connected) {
      var subs = this.stompClient.subscribe(topic, (message) => {
        callback(message.body);
      });
      // console.log("Subscribed to ", topic);
      return subs;
    }
  }

  unsubscribe() {
    this.subscriptions.forEach(element => {
      element.unsubscribe();
      // console.log("Unsubscribed to ", element);
    });
  }
}

const webSocketService = new WebSocketService();
export default webSocketService;
