import { faker } from "@faker-js/faker";
import {
  Avatar,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  IconButton,
  Slide,
  Stack,
} from "@mui/material";
import React from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  ResetVideoCallQueue,
  UpdateVideoCallDialog,
} from "../../../redux/slices/videoCall";
import { PhoneCall, PhoneSlash, PhoneX } from "phosphor-react";
import webSocketService from "../../../webSocketService";
// import { socket } from "../../../socket";
// import { AWS_S3_REGION, S3_BUCKET_NAME } from "../../../config";

const Transition = React.forwardRef(function Transition(props, ref) {
  return <Slide direction="up" ref={ref} {...props} />;
});

const CallNotification = ({ open, handleClose }) => {
  const dispatch = useDispatch();
  const { user } = useSelector((state) => state.app);
  const [call_details] = useSelector((state) => state.videoCall.call_queue);
  const handleAccept = () => {
    // socket.emit("video_call_accepted", { ...call_details });
    webSocketService.sendMessage("/app/video_call_accepted",JSON.stringify({...call_details}));
    dispatch(UpdateVideoCallDialog({ state: true }));
  };

  const handleDeny = () => {
    // socket.emit("video_call_denied", { ...call_details });
    webSocketService.sendMessage("/app/video_call_denied",JSON.stringify({...call_details}));
    dispatch(ResetVideoCallQueue());
    handleClose();
  };

  return (
    <>
      <Dialog
        open={open}
        TransitionComponent={Transition}
        keepMounted
        onClose={handleDeny}
        aria-describedby="alert-dialog-slide-description"
      >
        <DialogContent>
          <Stack direction="row" spacing={24} p={2}>
            <Stack>
              <Avatar
                sx={{ height: 100, width: 100 }}
                src={call_details?.from?.avatar}
              />
            </Stack>
            <Stack>
              <Avatar
                sx={{ height: 100, width: 100 }}
                src={user?.avatar}
              />
            </Stack>
          </Stack>
        </DialogContent>
        <DialogActions>
          <IconButton onClick={handleAccept} variant="contained" color="success">
            <PhoneCall size={40}/>
            Accept
          </IconButton>
          <IconButton onClick={handleDeny} variant="contained" color="error">
            <PhoneX size={40}/>
            Deny
          </IconButton>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default CallNotification;